<?php
declare(strict_types=1);
require __DIR__ . '/includes/lib.php';
$user=require_login();if(!in_array($user['level'],['admin','mayor','officer'],true))forbidden('Only Admin, Mayor, and Officer accounts can view the college ledger.');
$pdo=db();$collegeId=(int)($user['college_id']??0);$collegeFilter=(int)($_GET['college_id']??0);
if($user['level']!=='admin' && $collegeId<1)forbidden('Your account is not linked to a college. Ask the administrator to check your college assignment.');
if($user['level']!=='admin')$collegeFilter=$collegeId;
$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));$sy=trim((string)($_GET['school_year']??''));
$valid=fn($d)=>$d===''||((($x=DateTime::createFromFormat('Y-m-d',$d))!==false)&&$x->format('Y-m-d')===$d);if(!$valid($from))$from='';if(!$valid($to))$to='';if($sy!==''&&!preg_match('/^\d{4}-\d{4}$/',$sy))$sy='';
$base="SELECT c.collection_date tx_date,'Collection' kind,c.receipt_no reference_no,CONCAT(s.last_name,', ',s.first_name,' · ',fs.source_name) detail,c.amount inflow,0 outflow,cl.college_name college_name,c.school_year,0 university_share FROM collection c JOIN student s ON s.student_id=c.student_id JOIN fund_source fs ON fs.source_id=c.source_id JOIN college cl ON cl.college_id=c.college_id UNION ALL SELECT e.expense_date,'Expense',e.voucher_no,CONCAT(p.title,' · ',ec.category_name),0,e.amount,cl.college_name,e.school_year,0 FROM expense e JOIN project p ON p.project_id=e.project_id JOIN budget b ON b.budget_id=p.budget_id JOIN officer o ON o.officer_id=p.officer_id JOIN student s ON s.student_id=o.student_id JOIN college cl ON cl.college_id=e.college_id JOIN expense_category ec ON ec.category_id=e.category_id UNION ALL SELECT DATE(COALESCE(sp.verified_at,sp.paid_at,sp.created_at)),'Student fee',COALESCE(sp.receipt_no,CONCAT('PAY-',sp.payment_id)),CONCAT(s.last_name,', ',s.first_name,' · ',pr.fee_name),sp.college_share,0,cl.college_name,sp.school_year,sp.university_share FROM student_payment sp JOIN student s ON s.student_id=sp.student_id JOIN college cl ON cl.college_id=sp.college_id JOIN payment_requirement pr ON pr.requirement_id=sp.requirement_id WHERE sp.status='Verified'";
$sql='SELECT * FROM ('.$base.') x WHERE 1=1';$params=[];if($collegeFilter){$sql.=' AND college_name=(SELECT college_name FROM college WHERE college_id=?)';$params[]=$collegeFilter;}if($from!==''){$sql.=' AND tx_date>=?';$params[]=$from;}if($to!==''){$sql.=' AND tx_date<=?';$params[]=$to;}if($sy!==''){$sql.=' AND school_year=?';$params[]=$sy;}$sql.=' ORDER BY tx_date DESC,reference_no DESC';
$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$in=$out=$university=0;foreach($rows as $r){$in+=(float)$r['inflow'];$out+=(float)$r['outflow'];$university+=(float)$r['university_share'];}
$colleges=$user['level']==='admin'?$pdo->query('SELECT college_id,college_name FROM college ORDER BY college_name')->fetchAll():[];
$years=$pdo->query('SELECT school_year FROM budget WHERE school_year IS NOT NULL UNION SELECT school_year FROM collection WHERE school_year IS NOT NULL UNION SELECT school_year FROM expense WHERE school_year IS NOT NULL UNION SELECT school_year FROM student_payment WHERE school_year IS NOT NULL ORDER BY school_year DESC')->fetchAll(PDO::FETCH_COLUMN);
page_start('College history','college_ledger'); ?>
<div class="head"><div><h1><?= $user['level']==='admin'?'University financial history':'College financial history' ?></h1><p class="muted">Filter by college, date range, and school year. Historical entries are retained.</p></div></div>
<form method="get" class="search"><?php if($user['level']==='admin'): ?><label class="inline">College<select name="college_id"><option value="0">All colleges</option><?php foreach($colleges as $c): ?><option value="<?=(int)$c['college_id']?>" <?=$collegeFilter===(int)$c['college_id']?'selected':''?>><?=e($c['college_name'])?></option><?php endforeach;?></select></label><?php endif; ?><label class="inline">School year<select name="school_year"><option value="">All years</option><?php foreach($years as $y): ?><option value="<?=e($y)?>" <?=$sy===$y?'selected':''?>><?=e($y)?></option><?php endforeach;?></select></label><label class="inline">From<input type="date" name="from" value="<?=e($from)?>"></label><label class="inline">To<input type="date" name="to" value="<?=e($to)?>"></label><button class="btn">Filter</button><a class="btn ghost" href="college_ledger.php">Reset</a></form>
<section class="cards"><div class="stat in"><span>College inflow</span><strong><?=money($in)?></strong></div><div class="stat"><span>University 30% share</span><strong><?=money($university)?></strong></div><div class="stat out"><span>Expenses</span><strong><?=money($out)?></strong></div><div class="stat bal"><span>College net</span><strong><?=money($in-$out)?></strong></div></section>
<div class="card tablewrap"><table><thead><tr><th>Date</th><th>College</th><th>School year</th><th>Type</th><th>Reference</th><th>Details</th><th class="num">College in</th><th class="num">University share</th><th class="num">Out</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['tx_date'])?></td><td><?=e($r['college_name'])?></td><td><?=e($r['school_year']??'—')?></td><td><?=e($r['kind'])?></td><td><?=e($r['reference_no'])?></td><td><?=e($r['detail'])?></td><td class="num pos"><?=$r['inflow']?money($r['inflow']):''?></td><td class="num"><?=$r['university_share']?money($r['university_share']):'—'?></td><td class="num neg"><?=$r['outflow']?money($r['outflow']):''?></td></tr><?php endforeach;?><?php if(!$rows): ?><tr><td colspan="9" class="empty">No transactions match these filters.</td></tr><?php endif;?></tbody></table></div>
<?php page_end(); ?>
